// session-pet.css
var session_pet_default = `.dchat-pet-root {
  --dchat-pet-fab-size: 38px;
  position: fixed;
  top: 56px;
  right: 16px;
  z-index: 1200;
  pointer-events: auto;
  user-select: none;
}

.dchat-pet-root[data-size='md'] {
  --dchat-pet-fab-size: 48px;
}

.dchat-pet-root[data-size='lg'] {
  --dchat-pet-fab-size: 60px;
}

.dchat-pet-fab {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--dchat-pet-fab-size);
  height: var(--dchat-pet-fab-size);
  padding: 0;
  border: 1px solid var(--dsw-alias-border-l2);
  border-radius: 999px;
  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-1));
  backdrop-filter: var(--dsw-menu-backdrop-filter);
  color: var(--dsw-alias-label-secondary);
  box-shadow: var(--dsw-elevation-soft);
  cursor: grab;
  touch-action: none;
  transition: transform 0.16s ease, color 0.16s ease, border-color 0.16s ease, opacity 0.2s ease, box-shadow 0.16s ease;
}

.dchat-pet-header-slot {
  position: relative;
  display: none;
  align-items: center;
}

@media (max-width: 767px) {
  .dchat-pet-root {
    display: none;
  }

  .dchat-pet-header-slot {
    display: inline-flex;
  }

  /* The native leading seat exists before the first Session. Anchor its
     trigger to the trailing edge and reserve the width beside the utilities. */
  header:has(> [data-conversation-header-leading] .dchat-pet-header-slot) {
    position: relative;
  }

  [data-conversation-header-leading] .dchat-pet-header-slot {
    position: absolute;
    inset-block-start: 10px;
    inset-inline-end: 12px;
  }

  [data-conversation-header-leading]:has(.dchat-pet-header-slot) + [data-slot="conversation.session.header"] > :first-child {
    padding-inline-end: 44px;
  }
}

.dchat-pet-fab .dchat-pet-svg {
  width: calc(var(--dchat-pet-fab-size) * 0.82);
  height: calc(var(--dchat-pet-fab-size) * 0.82);
}

.dchat-pet-header-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: var(--dsw-radius-sm);
  background: transparent;
  color: var(--dsw-alias-label-secondary);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.dchat-pet-header-btn:active {
  background: var(--dsw-alias-interactive-bg-active);
}

@media (hover: hover) {
  .dchat-pet-header-btn:hover {
    color: var(--dsw-alias-label-primary);
    background: var(--dsw-alias-interactive-bg-hover);
  }
}

.dchat-pet-header-btn .dchat-pet-svg {
  width: 30px;
  height: 30px;
  flex: none;
}

.dchat-pet-header-btn .dchat-pet-badge {
  position: absolute;
  top: 1px;
  right: 1px;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  min-width: 13px;
  height: 13px;
  padding: 0 3px;
  font-size: 9px;
  line-height: 13px;
  box-shadow: 0 0 0 1.5px var(--dsw-alias-bg-base);
}

.dchat .dchat-header-actions .dchat-pet-header-btn > .dchat-pet-badge {
  display: grid;
}

.dchat-pet-fab:hover {
  opacity: 1 !important;
  transform: translateY(-1px);
  color: var(--dsw-alias-label-primary);
}

.dchat-pet-fab:active {
  cursor: grabbing;
}

@media (prefers-reduced-motion: no-preference) {
  .dchat-pet-wheel {
    animation: dchat-pet-spin 1.2s linear infinite;
  }

  .dchat-pet-leg {
    transform-origin: 15px 22px;
    animation: dchat-pet-pedal .6s ease-in-out infinite alternate;
  }

  .dchat-pet-cup {
    transform-origin: 23px 29px;
    animation: dchat-pet-sip 5s ease-in-out infinite;
  }

  .dchat-pet-steam {
    animation: dchat-pet-steam 2s ease-out infinite;
  }

  .dchat-pet-flag {
    transform-origin: 22px 35px;
    animation: dchat-pet-wave 3s ease-in-out infinite;
  }

  .dchat-pet-check {
    transform-origin: 29px 29px;
    animation: dchat-pet-stamp .45s ease-out;
  }
}

@keyframes dchat-pet-spin {
  to { transform: rotate(360deg); }
}

@keyframes dchat-pet-pedal {
  from { transform: rotate(-13deg); }
  to { transform: rotate(16deg); }
}

@keyframes dchat-pet-sip {
  0%, 50%, 100% { transform: none; }
  66%, 78% { transform: translate(-1px, -4px) rotate(-12deg); }
}

@keyframes dchat-pet-steam {
  from { opacity: .9; }
  to { opacity: 0; transform: translateY(-3px); }
}

@keyframes dchat-pet-wave {
  0%, 40%, 100% { transform: none; }
  12%, 32% { transform: rotate(-12deg); }
  22% { transform: rotate(7deg); }
}

@keyframes dchat-pet-stamp {
  0% { transform: scale(.5); }
  65% { transform: scale(1.13); }
  100% { transform: scale(1); }
}

.dchat-pet-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  box-sizing: border-box;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 999px;
  background: var(--dsw-alias-label-primary);
  color: var(--dsw-alias-bg-base);
  box-shadow: 0 0 0 1.5px var(--dsw-alias-bg-base);
  font-size: 9px;
  font-weight: 600;
  line-height: 15px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.dchat-pet-badge[data-mood='running'] {
  background: var(--dsw-alias-state-info-primary, #2563eb);
  color: #fff;
}

.dchat-pet-badge[data-mood='attention'] {
  background: var(--dsw-alias-state-warn-label, #d97706);
  color: #fff;
}

.dchat-pet-badge[data-mood='done'] {
  background: var(--dsw-alias-state-success-primary, #16a34a);
  color: #fff;
}

.dchat-pet-panel {
  position: absolute;
  right: 0;
  bottom: calc(var(--dchat-pet-fab-size) + 12px);
  width: min(320px, calc(100vw - 24px));
  max-height: min(380px, calc(100dvh - 100px));
  display: flex;
  flex-direction: column;
  padding: 10px;
  border: 0.5px solid var(--dsw-alias-border-l2);
  border-radius: var(--dsw-radius-lg);
  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-1));
  backdrop-filter: var(--dsw-menu-backdrop-filter);
  box-shadow: var(--dsw-elevation-prominent);
  color: var(--dsw-alias-label-primary);
}

.dchat-pet-panel[data-below] {
  bottom: auto;
  top: calc(var(--dchat-pet-fab-size) + 12px);
}

.dchat-pet-panel[data-align-left] {
  right: auto;
  left: 0;
}

.dchat-pet-bubble {
  position: absolute;
  right: 0;
  bottom: calc(var(--dchat-pet-fab-size) + 10px);
  width: min(310px, calc(100vw - 24px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 0.5px solid var(--dsw-alias-border-l2);
  border-radius: var(--dsw-radius-lg);
  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-1));
  backdrop-filter: var(--dsw-menu-backdrop-filter);
  box-shadow: var(--dsw-elevation-prominent);
  color: var(--dsw-alias-label-primary);
  animation: dchat-pet-bubble-in 0.16s ease-out;
}

.dchat-pet-bubble[data-below] {
  bottom: auto;
  top: calc(var(--dchat-pet-fab-size) + 10px);
}

.dchat-pet-bubble[data-align-left] {
  right: auto;
  left: 0;
}

@keyframes dchat-pet-bubble-in {
  from { opacity: 0; transform: translateY(4px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

.dchat-pet-bubble-head {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.dchat-pet-bubble-task {
  flex: 1 1 auto;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--dsw-alias-label-secondary);
  font-size: 12px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
}

.dchat-pet-bubble-task:hover {
  color: var(--dsw-alias-label-primary);
}

.dchat-pet-bubble-task > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dchat-pet-bubble-more {
  flex: none;
  padding: 1px 6px;
  border: 0;
  border-radius: 999px;
  background: var(--dsw-alias-interactive-bg-hover);
  color: var(--dsw-alias-label-secondary);
  font-size: 11px;
  cursor: pointer;
}

.dchat-pet-bubble-more:hover {
  color: var(--dsw-alias-label-primary);
}

.dchat-pet-bubble-close {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 3px;
  border: 0;
  border-radius: var(--dsw-radius-sm);
  background: transparent;
  color: var(--dsw-alias-label-tertiary);
  cursor: pointer;
}

.dchat-pet-bubble-close:hover {
  color: var(--dsw-alias-label-primary);
  background: var(--dsw-alias-interactive-bg-hover);
}

.dchat-pet-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 4px 8px;
  border-bottom: 0.5px solid var(--dsw-alias-border-l2);
}

.dchat-pet-panel-title {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}

.dchat-pet-panel-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.dchat-pet-size-group {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border-radius: var(--dsw-radius-sm);
  background: var(--dsw-alias-bg-layer-1);
}

.dchat-pet-size-btn {
  border: 0;
  border-radius: calc(var(--dsw-radius-sm) - 2px);
  background: transparent;
  color: var(--dsw-alias-label-tertiary);
  font-size: 11px;
  line-height: 16px;
  padding: 1px 5px;
  cursor: pointer;
}

.dchat-pet-size-btn:hover {
  color: var(--dsw-alias-label-primary);
}

.dchat-pet-size-btn[data-active] {
  background: var(--dsw-alias-bg-base);
  color: var(--dsw-alias-label-primary);
  font-weight: 500;
}

.dchat-pet-ack,
.dchat-pet-sound,
.dchat-pet-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--dsw-radius-sm);
  background: transparent;
  color: var(--dsw-alias-label-tertiary);
  font-size: 12px;
  cursor: pointer;
  padding: 2px 6px;
}

.dchat-pet-sound {
  padding: 3px;
}

.dchat-pet-sound[data-enabled] {
  color: var(--dsw-alias-label-secondary);
}

.dchat-pet-ack:hover,
.dchat-pet-sound:hover,
.dchat-pet-close:hover {
  color: var(--dsw-alias-label-primary);
  background: var(--dsw-alias-interactive-bg-hover);
}

.dchat-pet-empty {
  padding: 18px 8px;
  color: var(--dsw-alias-label-tertiary);
  font-size: 12px;
  text-align: center;
}

.dchat-pet-empty p {
  margin: 0;
}

.dchat-pet-list {
  list-style: none;
  margin: 6px 0 0;
  padding: 0;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dchat-pet-list > li {
  flex-shrink: 0;
  border-radius: var(--dsw-radius-md);
  overflow: hidden;
}

.dchat-pet-list > li:has(.dchat-pet-approval) {
  border: 0;
  background: var(--dsw-alias-bg-layer-1);
}

.dchat-pet-list > li:has(.dchat-pet-approval) .dchat-pet-item {
  border-radius: 0;
}

.dchat-pet-item {
  position: relative;
  isolation: isolate;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  border: 0;
  border-radius: var(--dsw-radius-md);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.dchat-pet-item:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}

.dchat-pet-item-logo {
  flex: none;
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
}

.dchat-pet-item-logo img {
  object-fit: contain;
  border-radius: 3px;
}

.dchat-pet-item[data-live-state]::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
}

.dchat-pet-item[data-live-state="running"] {
  box-shadow: inset 2.5px 0 0 color-mix(in srgb, var(--dsw-alias-state-business-primary, #3b82f6) 75%, transparent);
}

.dchat-pet-item[data-live-state="running"]::before {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--dsw-alias-state-business-primary, #3b82f6) 4%, transparent) 0%,
    color-mix(in srgb, var(--dsw-alias-state-business-primary, #3b82f6) 13%, transparent) 50%,
    color-mix(in srgb, var(--dsw-alias-state-business-primary, #3b82f6) 4%, transparent) 100%
  );
  background-size: 200% 100%;
  animation: dchat-row-flow 2.5s ease-in-out infinite;
}

.dchat-pet-item[data-live-state="attention"] {
  box-shadow: inset 2.5px 0 0 color-mix(in srgb, var(--dsw-alias-state-warn-label, #f59e0b) 85%, transparent);
}

.dchat-pet-item[data-live-state="attention"]::before {
  background: color-mix(in srgb, var(--dsw-alias-state-warn-label, #f59e0b) 12%, transparent);
  animation: dchat-row-breathe 2.2s ease-in-out infinite;
}

.dchat-pet-item[data-live-state="done"] {
  box-shadow: inset 2.5px 0 0 color-mix(in srgb, var(--dsw-alias-state-success-primary, #22c55e) 70%, transparent);
}

.dchat-pet-item[data-live-state="done"]::before {
  background: color-mix(in srgb, var(--dsw-alias-state-success-primary, #22c55e) 8%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .dchat-pet-item[data-live-state="running"]::before,
  .dchat-pet-item[data-live-state="attention"]::before {
    animation: none;
  }
}

.dchat-pet-item-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1 1 auto;
  gap: 2px;
}

.dchat-pet-approval {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 8px 10px 10px;
  border: 0;
  border-top: 0.5px solid var(--dsw-alias-border-l3);
  border-radius: 0;
  background: transparent;
}

.dchat-pet-approval-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.dchat-pet-approval-card + .dchat-pet-approval-card {
  padding-top: 8px;
  border-top: 0.5px solid var(--dsw-alias-border-l3);
}

.dchat-pet-approval-title {
  font-size: 12.5px;
  line-height: 18px;
  font-weight: 600;
  color: var(--dsw-alias-label-primary);
  overflow-wrap: anywhere;
}

.dchat-pet-approval-detail {
  max-height: 76px;
  padding: 6px 8px;
  overflow: auto;
  border-radius: var(--dsw-radius-sm, 6px);
  border: 0;
  background: var(--dsw-alias-bg-base);
  font-size: 11.5px;
  line-height: 1.45;
  font-family: var(--ds-font-family-code, monospace);
  color: var(--dsw-alias-label-secondary);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.dchat-pet-approval-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  margin-top: 2px;
}

.dchat-pet-item-title {
  font-size: 13px;
  line-height: 18px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dchat-pet-item-meta {
  font-size: 11px;
  line-height: 15px;
  color: var(--dsw-alias-label-tertiary);
}

.dchat-pet-panel-fullscreen[role="dialog"] {
  --dchat-pet-inline-start: max(16px, env(safe-area-inset-left));
  --dchat-pet-inline-end: max(16px, env(safe-area-inset-right));
  position: fixed;
  inset: var(--dsh-frame-overlay-top, 0px) 0 0;
  gap: 0;
  width: auto;
  padding: env(safe-area-inset-top) 0 env(safe-area-inset-bottom);
  border-radius: 0;
  background: var(--dsw-alias-bg-base);
  color: var(--dsw-alias-label-primary);
  box-shadow: none;
}

.dchat-pet-panel-fullscreen .dchat-pet-panel-header {
  flex: none;
  min-height: 54px;
  padding: 0 max(6px, env(safe-area-inset-right)) 0 var(--dchat-pet-inline-start);
  border-bottom: 0.5px solid var(--dsw-alias-border-l3);
}

.dchat-pet-panel-fullscreen .dchat-pet-panel-title {
  font-size: 16px;
  line-height: 24px;
}

.dchat-pet-panel-fullscreen .dchat-pet-panel-actions {
  gap: 2px;
}

.dchat-pet-panel-fullscreen :is(.dchat-pet-ack, .dchat-pet-sound, .dchat-pet-close) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  color: var(--dsw-alias-label-secondary);
}

.dchat-pet-panel-fullscreen .dchat-pet-ack {
  padding: 0 8px;
  white-space: nowrap;
}

.dchat-pet-panel-fullscreen .dchat-pet-sound,
.dchat-pet-panel-fullscreen .dchat-pet-close {
  width: 44px;
}

.dchat-pet-panel-fullscreen .dchat-pet-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding-inline: var(--dchat-pet-inline-start) var(--dchat-pet-inline-end);
  font-size: 14px;
  line-height: 20px;
}

.dchat-pet-panel-fullscreen .dchat-pet-empty .dchat-pet-svg {
  box-sizing: content-box;
  width: 38px;
  height: 38px;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid var(--dsw-alias-border-l3);
  background: var(--dsw-alias-bg-layer-1);
  color: var(--dsw-alias-label-secondary);
}

.dchat-pet-panel-fullscreen .dchat-pet-list {
  min-height: 0;
  margin: 0;
  padding: 12px var(--dchat-pet-inline-end) 18px var(--dchat-pet-inline-start);
  overscroll-behavior: contain;
  gap: 10px;
}

.dchat-pet-panel-fullscreen .dchat-pet-list > li {
  border-radius: var(--dsw-radius-lg, 12px);
  border: 0;
  background: var(--dsw-alias-bg-layer-1);
  overflow: hidden;
}

.dchat-pet-panel-fullscreen .dchat-pet-item {
  min-height: 58px;
  padding: 12px 14px;
  gap: 12px;
  border-radius: 0;
}

.dchat-pet-panel-fullscreen .dchat-pet-item-logo {
  width: 30px;
  height: 30px;
  border-radius: var(--dsw-radius-sm, 6px);
  background: var(--dsw-alias-bg-base);
  border: 0.5px solid var(--dsw-alias-border-l3);
}

.dchat-pet-panel-fullscreen .dchat-pet-approval {
  margin: 0;
  padding: 10px 14px 12px;
  border: 0;
  border-top: 0.5px solid var(--dsw-alias-border-l3);
  border-radius: 0;
  background: transparent;
}

.dchat-pet-panel-fullscreen .dchat-pet-approval-title {
  font-size: 13px;
  line-height: 19px;
}

.dchat-pet-panel-fullscreen .dchat-pet-approval-detail {
  max-height: 96px;
  font-size: 12px;
}

.dchat-pet-panel-fullscreen .dchat-pet-approval-actions {
  gap: 8px;
  margin-top: 4px;
}

.dchat-pet-panel-fullscreen .dchat-pet-approval-actions button {
  flex: 1 1 auto;
  min-height: 36px;
}

.dchat-pet-panel-fullscreen .dchat-pet-item-title {
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

.dchat-pet-panel-fullscreen .dchat-pet-item-meta,
.dchat-pet-item-status {
  font-size: 12px;
  line-height: 16px;
}

.dchat-pet-item-status {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 5px;
  max-width: 40%;
  text-align: end;
  color: var(--dsw-alias-label-secondary);
}

.dchat-pet-item-status > :is(svg, span) {
  flex: none;
}

.dchat-pet-item-chevron {
  flex: none;
  color: var(--dsw-alias-label-tertiary);
}

@media (prefers-reduced-motion: reduce) {
  .dchat-pet-fab {
    transition: none;
  }
}
`;

